// ── Factorial and basic combinatorics ────────────────────────
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

function permutations(n, r) {
  return factorial(n) / factorial(n - r);
}

function combinations(n, r) {
  return factorial(n) / (factorial(r) * factorial(n - r));
}

console.log('P(10,3) - medals:', permutations(10, 3)); // 720
console.log('C(10,3) - committee:', combinations(10, 3)); // 120
console.log('C(52,5) - poker hands:', combinations(52, 5)); // 2598960

// ── Verify 2^n subsets via binomial theorem ───────────────────
// Sum of C(n,k) for k=0..n should equal 2^n
const n = 10;
const sumBinomial = Array.from({length: n+1}, (_, k) => combinations(n, k))
  .reduce((a, b) => a + b, 0);
console.log(`Sum C(${n},k) k=0..${n}:`, sumBinomial); // 1024 = 2^10
console.log('2^n:', Math.pow(2, n)); // 1024

// ── Inclusion-Exclusion ───────────────────────────────────────
// Students: |CS|=30, |Math|=25, |CS∩Math|=10
// |CS∪Math| = 30 + 25 - 10 = 45
const cs = new Set([...Array.from({length:30}, (_,i) => i)]);
const math = new Set([...Array.from({length:25}, (_,i) => i + 20)]);
// overlap: indices 20-29 (10 students)
const union = new Set([...cs, ...math]);
const intersection = new Set([...cs].filter(x => math.has(x)));
console.log('|CS|:', cs.size, '|Math|:', math.size);
console.log('|CS∩Math|:', intersection.size); // 10
console.log('|CS∪Math| via sets:', union.size); // 45
console.log('|CS∪Math| via I-E:', cs.size + math.size - intersection.size); // 45

// ── Pigeonhole: birthday collision probability (approx) ───────
// P(no collision among k people) = 365/365 * 364/365 * ... * (365-k+1)/365
function birthdayCollisionProb(k, days = 365) {
  let pNoCollision = 1;
  for (let i = 0; i < k; i++) {
    pNoCollision *= (days - i) / days;
  }
  return 1 - pNoCollision;
}
console.log('P(collision, 23 people):', birthdayCollisionProb(23).toFixed(4)); // ~0.5073
console.log('P(collision, 57 people):', birthdayCollisionProb(57).toFixed(4)); // ~0.99

// ── Pascal's triangle — efficient combinations ────────────────
// C(n,k) = C(n-1,k-1) + C(n-1,k)  — avoids large factorials
function buildPascal(rows) {
  const triangle = [[1]];
  for (let n = 1; n < rows; n++) {
    const prev = triangle[n - 1];
    const row = [1];
    for (let k = 1; k < n; k++) {
      row.push(prev[k-1] + prev[k]);
    }
    row.push(1);
    triangle.push(row);
  }
  return triangle;
}

const pascal = buildPascal(7);
pascal.forEach((row, n) => {
  console.log(`Row ${n}: [${row.join(', ')}]  sum=${row.reduce((a,b)=>a+b,0)} = 2^${n}`);
});

// ── Stirling's approximation for large factorials ─────────────
// n! ≈ sqrt(2πn) * (n/e)^n  — log of factorial for algorithm analysis
function logFactorial(n) {
  // Use Stirling: ln(n!) ≈ n*ln(n) - n + 0.5*ln(2πn)
  if (n <= 1) return 0;
  return n * Math.log(n) - n + 0.5 * Math.log(2 * Math.PI * n);
}

// Number of bits to represent C(200,100):
const logC200_100 = logFactorial(200) - 2 * logFactorial(100);
console.log('ln C(200,100):', logC200_100.toFixed(2));
console.log('bits needed:', Math.ceil(logC200_100 / Math.log(2))); // ~198 bits

// ── Pigeonhole generalisation ────────────────────────────────
// Among n*k + 1 items in n bins, some bin has >= k+1
function pigeonholeGuarantee(items, bins) {
  // Minimum guaranteed maximum in any bin
  return Math.floor((items - 1) / bins) + 1;
}
console.log('367 people, 366 days → min shared birthday count:',
  pigeonholeGuarantee(367, 366)); // 2 (guaranteed at least 2 share a day)
